answer = 37
guesses = [50, 25, 37, 40]
tries = 0
for g in guesses:
    tries += 1
    if g == answer:
        print(f"{g}: 정답이에요. {tries}번 만에 맞혔어요")
        break
    elif g > answer:
        print(f"{g}: 더 작아요")
    else:
        print(f"{g}: 더 커요")
